head.script:
scwin.onpageload = function() {
};

scwin.onpageunload = function() {

};

scwin.checkVal = function() {
	return WebSquare.wUnit.getDomById('secondWframe1_mf_secondWframe1_wq_processMsgComp').style.display == 'none';
}
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('secondWframe1_trigger2').click()");
	WebSquare.wUnit.addCommand("pause", "500");			

	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest();
